DROP TABLE IF EXISTS `custom_store_special_offer`;
CREATE TABLE `custom_store_special_offer` (
  `offerID` mediumint(8) unsigned NOT NULL DEFAULT '0',
  `background` varchar(255),
  `headline` varchar(255),
  `title` varchar(255),
  `description` varchar(255),
  `detailsTitle` varchar(255),
  `details` mediumint(8) unsigned NOT NULL DEFAULT '0',
  `time` int(10) unsigned NOT NULL DEFAULT '0',
  `productID` mediumint(8) unsigned NOT NULL DEFAULT '0',
  `itemEntry` mediumint(8) unsigned NOT NULL DEFAULT '0',
  `price` int(10) unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`offerID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `custom_store_special_offer_details`;
CREATE TABLE `custom_store_special_offer_details` (
  `detailsID` mediumint(8) unsigned NOT NULL DEFAULT '0',
  `itemID` mediumint(8) unsigned NOT NULL DEFAULT '0',
  `role` mediumint(8) unsigned NOT NULL DEFAULT '0',
  `count` mediumint(8) unsigned NOT NULL DEFAULT '1'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `custom_store_shop_version`;
CREATE TABLE `custom_store_shop_version` (
  `version` mediumint(8) unsigned NOT NULL DEFAULT '0'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `custom_store_mounts`;
CREATE TABLE `custom_store_mounts` (
  `id` mediumint(8) NOT NULL DEFAULT '0',
  `hash` varchar(255) NOT NULL DEFAULT '0',
  `currency` mediumint(8) unsigned NOT NULL DEFAULT '0',
  `price` mediumint(8) unsigned NOT NULL DEFAULT '0',
  `productID` mediumint(8) unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `hash` (`hash`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `custom_store_logs`;
CREATE TABLE `custom_store_logs` (
  `character_ID` mediumint(8) unsigned NOT NULL DEFAULT '0',
  `character_name` varchar(255),
  `account_ID` mediumint(8) unsigned NOT NULL DEFAULT '0',
  `serviceName` varchar(255),
  `itemID` int(10) unsigned NOT NULL DEFAULT '0',
  `itemCount` mediumint(8) unsigned NOT NULL DEFAULT '0',
  `totalPrice` int(10) unsigned NOT NULL DEFAULT '0',
  `time` int(10) unsigned NOT NULL DEFAULT '0'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DELETE FROM `custom_store_shop_version`;
INSERT INTO `custom_store_shop_version` (`version`) VALUES (1);
